"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import os
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request


class InvalidCursor(Exception):
    """The server rejected the cursor; the export must start over."""


def _get_json(url, timeout=30, max_rate_limit_retries=10):
    """GET url, retrying rate-limited requests with the identical URL."""
    retries = 0
    while True:
        try:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                if retries >= max_rate_limit_retries:
                    raise
                retries += 1
                retry_after = exc.headers.get("Retry-After", "1")
                try:
                    delay = float(retry_after)
                except ValueError:
                    delay = 1.0
                time.sleep(max(0.0, delay))
                continue
            if exc.code == 400:
                body = exc.read()
                try:
                    error = json.loads(body).get("error")
                except (ValueError, AttributeError):
                    error = None
                if error == "invalid_cursor":
                    raise InvalidCursor() from exc
            raise


def fetch_payouts(base_url):
    """Export every payout once, following cursors until the export drains."""
    payouts = []
    seen_ids = set()
    cursor = None
    restarted = False

    while True:
        query = {}
        if cursor is not None:
            query["cursor"] = cursor
        url = f"{base_url}/v2/payouts"
        if query:
            url += "?" + urllib.parse.urlencode(query)

        try:
            data = _get_json(url)
        except InvalidCursor:
            if restarted or cursor is None:
                raise
            # Restart the export from the beginning. Payouts are immutable and
            # IDs are unique, so already-seen payouts are simply skipped.
            restarted = True
            cursor = None
            continue

        for payout in data["payouts"]:
            payout_id = payout["id"]
            if payout_id in seen_ids:
                continue
            seen_ids.add(payout_id)
            payouts.append(payout)

        if data["drained"]:
            break
        cursor = data["cursor"]

    return payouts


def write_payouts(payouts, out_path):
    """Write the complete result atomically so a failed run leaves no partial file."""
    out_dir = os.path.dirname(os.path.abspath(out_path)) or "."
    fd, tmp_path = tempfile.mkstemp(prefix=".payouts-", suffix=".jsonl", dir=out_dir)
    try:
        with os.fdopen(fd, "w") as f:
            for p in payouts:
                f.write(json.dumps(p) + "\n")
        os.replace(tmp_path, out_path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    write_payouts(payouts, args.out)
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

